import bpy
for o in bpy.context.scene.objects:
    mats=[s.material.name if s.material else None for s in o.material_slots]
    mods=[f"{m.name}({m.type})" for m in o.modifiers]
    cp={k:(v if isinstance(v,(int,float,str)) else str(v)) for k,v in o.items() if k not in ('_RNA_UI',)}
    print(f"name={o.name} | type={o.type} | location={tuple(round(x,4) for x in o.location)} | rotation={tuple(round(x,4) for x in o.rotation_euler)} | scale={tuple(round(x,4) for x in o.scale)} | dimensions={tuple(round(x,4) for x in o.dimensions)} | parent={o.parent.name if o.parent else None} | materials={mats} | modifiers={mods} | custom_props={cp}")

